    internal partial class PerkCardBinaryCreateTranslation : Fallout76MajorRecordBinaryCreateTranslation
    {
        public new static readonly PerkCardBinaryCreateTranslation Instance = new PerkCardBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.PCRD;
        public static ParseResult FillBinaryRecordTypes(
            IPerkCardInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                            item: item,
                            frame: frame,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            nextRecordType: nextRecordType,
                            contentLength: contentLength,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.EDID = StringBinaryTranslation.Instance.Parse(
                            reader: frame.SpawnWithLength(contentLength),
                            stringBinaryType: StringBinaryType.NullTerminate,
                            parseWhole: true);
                        return new ParseResult((int)PerkCard_FieldIndex.EDID, nextRecordType);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(nextRecordType) ?? 0)
                        {
                            case 0:
                                return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                                    item: item,
                                    frame: frame,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    nextRecordType: nextRecordType,
                                    contentLength: contentLength,
                                    translationParams: translationParams.WithNoConverter());
                            case 1:
                                frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                                item.EDID = StringBinaryTranslation.Instance.Parse(
                                    reader: frame.SpawnWithLength(contentLength),
                                    stringBinaryType: StringBinaryType.NullTerminate,
                                    parseWhole: true);
                                return new ParseResult((int)PerkCard_FieldIndex.EDID, nextRecordType);
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.DESC:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.DESC = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)PerkCard_FieldIndex.DESC;
                }
                case RecordTypeInts.PCDV:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.PerkData.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)PerkCard_FieldIndex.PerkData;
                }
                case RecordTypeInts.SNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Sound.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)PerkCard_FieldIndex.Sound;
                }
                case RecordTypeInts.MNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MNAM = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)PerkCard_FieldIndex.MNAM;
                }
                case RecordTypeInts.FNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FNAM = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)PerkCard_FieldIndex.FNAM;
                }
                case RecordTypeInts.ANAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ANAM = frame.ReadUInt32();
                    return (int)PerkCard_FieldIndex.ANAM;
                }
                case RecordTypeInts.DATA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    var dataFrame = frame.SpawnWithLength(contentLength);
                    if (dataFrame.Remaining < 4) return null;
                    item.Value = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: dataFrame);
                    if (dataFrame.Remaining < 1) return null;
                    item.MinLevel = dataFrame.ReadUInt8();
                    if (dataFrame.Remaining < 1) return null;
                    item.Special = EnumBinaryTranslation<SpecialType, MutagenFrame, MutagenWriter>.Instance.Parse(
                        reader: dataFrame,
                        length: 1);
                    if (dataFrame.Remaining < 2) return null;
                    item.RaceRestriction = dataFrame.ReadUInt16();
                    return (int)PerkCard_FieldIndex.RaceRestriction;
                }
                case RecordTypeInts.PRKE:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.PRKE = frame.ReadBoolean();
                    return (int)PerkCard_FieldIndex.PRKE;
                }
                case RecordTypeInts.PRKF:
                {
                    item.PRKF = true;
                    return (int)PerkCard_FieldIndex.PRKF;
                }
                default:
                    return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
